<template><view class="screen"><view class="heading">{{titles[mode]}}</view><view v-if="['login','sms'].includes(mode)" class="segments"><view @click="mode='login'">账号登录</view><view @click="mode='sms'">短信登录</view></view><view class="card"><input v-if="['login','register','sms_register'].includes(mode)" v-model="username" placeholder="用户名"/><input v-if="['login','register','sms_register','reset'].includes(mode)" v-model="password" password placeholder="密码"/><input v-if="mode==='register'" v-model="email" placeholder="邮箱"/><template v-if="mode!=='login'"><input v-model="tel" type="number" maxlength="14" placeholder="手机号" v-if="mode!=='register'"/><view class="row"><text @click="challenge">{{captcha?.question||'点击加载验证问题'}}</text><input v-model="verify" type="number" placeholder="答案"/></view><view v-if="mode!=='register'" class="row"><input v-model="code" type="number" maxlength="8" placeholder="短信验证码"/><button :disabled="countdown>0||busy" @click="send">{{countdown>0?countdown+'秒':'获取验证码'}}</button></view></template><template v-if="mode==='login'"><picker :range="questions" @change="questionid=Number($event.detail.value)"><view class="muted question">{{questions[questionid]}}</view></picker><input v-if="questionid" v-model="answer" placeholder="安全问题答案"/></template><view v-if="['register','sms_register'].includes(mode)" class="muted agreement" @click="agreed=!agreed">{{agreed?'☑':'☐'}} 我同意论坛用户规则与隐私说明</view><view v-if="error" class="error">{{error}}</view><button :disabled="busy" @click="submit">{{busy?'正在提交…':titles[mode]}}</button></view><view v-if="['login','sms'].includes(mode)" class="row links"><text @click="change('register')">账号注册</text><text @click="change('sms_register')">短信注册</text><text @click="change('reset')">找回密码</text></view><view class="muted legal" @click="openExternal('https://www.zozse.cn/member.php?mod=register')">查看论坛用户规则</view></view></template>
<script setup>
import { ref,onUnmounted } from 'vue'
import { onLoad } from '@dcloudio/uni-app'
import { request,post } from '../../api/index.js'
import { useAccount } from '../../store/account.js'
import { openExternal } from '../../utils/openExternal.js'
const titles={login:'账号登录',sms:'短信登录',register:'注册账号',sms_register:'短信注册',bind:'绑定手机号',unbind:'解绑手机号',reset:'找回密码'},questions=['无安全问题','母亲的名字','爷爷的名字','父亲出生的城市','您其中一位老师的名字','您个人计算机的型号','您最喜欢的餐馆名称','驾驶执照最后四位数字']
const account=useAccount(),mode=ref('login'),username=ref(''),password=ref(''),email=ref(''),tel=ref(''),code=ref(''),verify=ref(''),captcha=ref(null),questionid=ref(0),answer=ref(''),busy=ref(false),error=ref(''),countdown=ref(0),agreed=ref(false);let timer
async function challenge(){try{captcha.value=await request('auth/challenge.php');verify.value=''}catch(e){error.value=e.message}}
function change(m){mode.value=m;error.value='';code.value='';challenge()}
async function send(){if(busy.value||countdown.value)return;if(!tel.value||!verify.value){error.value='请输入手机号和验证答案';return}busy.value=true;error.value='';try{const actions={sms:'login',sms_register:'register',bind:'binding',unbind:'Unbundling',reset:'lostpw'};const d=await post('auth/sms_send.php',{tel:tel.value,action:actions[mode.value],challenge_id:captcha.value?.challenge_id,verify_code:verify.value});countdown.value=d.cooldown;clearInterval(timer);timer=setInterval(()=>{if(--countdown.value<=0)clearInterval(timer)},1000)}catch(e){error.value=e.message}finally{busy.value=false;challenge()}}
async function submit(){if(busy.value)return;if(['register','sms_register'].includes(mode.value)&&!agreed.value){error.value='请先阅读并同意论坛规则';return}busy.value=true;error.value='';try{const paths={login:'login',sms:'sms_login',register:'register',sms_register:'sms_register',bind:'sms_bind',unbind:'sms_bind',reset:'sms_lostpw'};const d=await post('auth/'+paths[mode.value]+'.php',{username:username.value,password:password.value,email:email.value,tel:tel.value,code:code.value,new_password:password.value,action:mode.value,challenge_id:captcha.value?.challenge_id,verify_code:verify.value,questionid:questionid.value,answer:answer.value});if(d.token)account.save(d);else if(['bind','unbind'].includes(mode.value))await account.refresh();uni.showToast({title:d.pending_review?'注册成功，等待审核':'操作成功',icon:'none'});if(mode.value==='reset'||d.pending_review)change('login');else uni.navigateBack({fail:()=>uni.reLaunch({url:'/pages/index/index'})})}catch(e){error.value=e.message;if(mode.value==='register')challenge()}finally{busy.value=false}}
onLoad(o=>{if(titles[o.mode])mode.value=o.mode;if(mode.value==='unbind')tel.value=account.user?.profile?.mobile||'';if(mode.value!=='login')challenge()});onUnmounted(()=>clearInterval(timer))
</script>
<style scoped>.screen{padding:30px 20px}.heading{font-size:32px;font-weight:800;margin:30px 0}.segments{display:flex;gap:28px;color:#007aff;margin-bottom:20px}input{margin-bottom:14px;background:var(--bg)}.row{display:flex;align-items:center;gap:12px;margin:14px 0}.row input{flex:1;min-width:0;margin:0}.row button{font-size:12px;padding:0 10px}.links{justify-content:space-between;color:#007aff;font-size:13px}.legal{text-align:center;margin:20px}.agreement{margin:20px 0}.question{padding:12px 0}</style>
